import * as React from 'react';
import { ArrowDownRight, ArrowUpRight } from 'lucide-react';

export type MetricTrend = 'up' | 'down' | 'flat';

export interface CrmMetricCardProps {
  title: string;
  value: string;
  delta?: string;
  trend?: MetricTrend;
}

/** Compact KPI tile for CRM dashboards. */
export function CrmMetricCard({ title, value, delta, trend = 'up' }: CrmMetricCardProps) {
  const Icon = trend === 'down' ? ArrowDownRight : ArrowUpRight;
  const tone = trend === 'down' ? 'text-red-600 bg-red-50' : 'text-emerald-600 bg-emerald-50';

  return (
    <div className="rounded-lg border border-slate-200 bg-white p-4 shadow-sm">
      <p className="text-xs font-medium uppercase tracking-wide text-slate-500">{title}</p>
      <div className="mt-2 flex items-end justify-between gap-3">
        <span className="text-2xl font-semibold tracking-tight text-slate-900">{value}</span>
        {delta ? (
          <span className={`inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-xs font-medium ${tone}`}>
            <Icon className="h-3 w-3" />
            {delta}
          </span>
        ) : null}
      </div>
    </div>
  );
}

import * as React from 'react';
import { CrmMetricCard } from '../components/data-metric';

/** Preview fixture rendered by the catalogue and the admin draft inspector. */
export default function CrmMetricCardPreview() {
  return (
    <div className="grid gap-3 sm:grid-cols-2">
      <CrmMetricCard title="Total Revenue" value="$45,231" delta="+12.5%" trend="up" />
      <CrmMetricCard title="Churned Accounts" value="18" delta="-3.1%" trend="down" />
    </div>
  );
}
